package br.com.sergio.gestaopedidos.repository;
import br.com.sergio.gestaopedidos.entity.ItemCompraInsumo;import br.com.sergio.gestaopedidos.enums.TipoMovimentacaoEstoque;import org.springframework.data.domain.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;
public interface ItemCompraInsumoRepository extends JpaRepository<ItemCompraInsumo,Long>{@EntityGraph(attributePaths={"insumo","compra"})@Query("SELECT i FROM ItemCompraInsumo i WHERE i.compra.status=br.com.sergio.gestaopedidos.enums.StatusCompraInsumo.ATIVA AND NOT EXISTS(SELECT m.id FROM MovimentacaoEstoque m WHERE m.itemCompraInsumo=i AND m.tipo=:tipo) ORDER BY i.compra.dataCompra,i.compra.id,i.id")Slice<ItemCompraInsumo> buscarSemMovimento(@Param("tipo")TipoMovimentacaoEstoque tipo,Pageable pageable);}
